def max_sum(arr):
    if not arr:
        return 0
    if len(arr) == 1:
        return arr[0]
    return max(arr[0], arr[-1]) + max(
        max_sum(arr[1:-1]), max(arr[1], arr[-1]) + max_sum(arr[2:-1])
    )
```

